    --text-secondary: #64748b;
    --text-muted: #94a3b8;

    --outer-shadow: 10px 14px 28px rgba(166, 180, 200, 0.6), -8px -8px 20px rgba(255, 255, 255, 0.95);
    --outer-shadow-hover: 14px 20px 36px rgba(150, 168, 192, 0.7), -10px -10px 24px rgba(255, 255, 255, 1);
    --outer-shadow-sm: 6px 8px 16px rgba(166, 180, 200, 0.5), -4px -4px 12px rgba(255, 255, 255, 0.9);

