/* ==========================================================================
   SKELETON SHIMMER LOADING EFFECT
   ========================================================================== */
.skeleton-box {
    background: linear-gradient(90deg, var(--clay-card-bg) 25%, var(--skeleton-bg) 50%, var(--clay-card-bg) 75%);
    background-size: 200% 100%;
    animation: shimmer 1.2s infinite;
    border-radius: 12px;
}
@keyframes shimmer {
    0% { background-position: 200% 0; }
    100% { background-position: -200% 0; }
}

.is-loading .kpi-value,
.is-loading .stat-pill-val,
.is-loading .donut-total {
    color: transparent !important;
    background: linear-gradient(90deg, var(--clay-card-bg) 25%, var(--skeleton-bg) 50%, var(--clay-card-bg) 75%);
    background-size: 200% 100%;
    animation: shimmer 1.2s infinite;
    border-radius: 8px;
    pointer-events: none;
}

